('9400', '94', 'Ingresos de subvenciones oficiales de capital', '["ECPN, parte A (ingresos y gastos reconocidos) › III. Subvenciones, donaciones y legados recibidos"]'::jsonb),
('9410', '94', 'Ingresos de donaciones y legados de capital', '["ECPN, parte A (ingresos y gastos reconocidos) › III. Subvenciones, donaciones y legados recibidos"]'::jsonb),
('9420', '94', 'Ingresos de otras subvenciones, donaciones y legados', '["ECPN, parte A (ingresos y gastos reconocidos) › III. Subvenciones, donaciones y legados recibidos"]'::jsonb)
insert into erp.pgc_cards (code, usage, debits, credits, balance, nrv, example_text, example_lines, warning) values
('100', 'Capital escriturado de la sociedad: lo que los socios se comprometen a aportar según la escritura de constitución o de ampliación.', '["Al reducir capital.", "Al cierre, si la sociedad se disuelve o liquida."]'::jsonb, '["Al constituir la sociedad o ampliar capital, una vez inscrito en el Registro Mercantil."]'::jsonb, 'Acreedor. Forma parte del patrimonio neto.', '[]'::jsonb, 'Constitución con 50.000 € ingresados en el banco.', '[{"subcuenta": "57200001", "nombre": "Banco", "debe": 50000, "haber": 0}, {"subcuenta": "10000000", "nombre": "Capital social", "debe": 0, "haber": 50000}]'::jsonb, 'En la práctica se suele ir directo a la 100. El PGC prevé un paso intermedio por la 190 y la 194 mientras la escritura no está inscrita.'),
('112', 'Reserva legal: parte del beneficio que la ley obliga a retener (en general, el 10 % del beneficio hasta que la reserva alcance el 20 % del capital).', '["Al aplicarla a compensar pérdidas o, en los casos permitidos, a ampliar capital."]'::jsonb, '["Al distribuir el resultado del ejercicio, con cargo a la 129."]'::jsonb, 'Acreedor. Patrimonio neto.', '[]'::jsonb, 'La junta destina 7.256,83 € del beneficio a reserva legal y el resto a voluntarias.', '[{"subcuenta": "12900000", "nombre": "Resultado del ejercicio", "debe": 81519.57, "haber": 0}, {"subcuenta": "11200000", "nombre": "Reserva legal", "debe": 0, "haber": 7256.83}, {"subcuenta": "11300000", "nombre": "Reservas voluntarias", "debe": 0, "haber": 74262.74}]'::jsonb, 'Es el asiento 74 de tu ejercicio de ContaSol.'),
('113', 'Reservas voluntarias: beneficios que los socios deciden no repartir y dejar en la empresa.', '["Al disponer de ellas: reparto de dividendos, compensación de pérdidas, ampliación de capital."]'::jsonb, '["Al distribuir el resultado, con cargo a la 129."]'::jsonb, 'Acreedor. Patrimonio neto.', '[]'::jsonb, 'Ver ejemplo de la cuenta 112.', '[]'::jsonb, ''),
('129', 'Resultado del ejercicio: beneficio o pérdida, pendiente de que la junta decida su destino.', '["Al regularizar, si hay pérdidas (contra los grupos 6 y 7).", "Al distribuir un beneficio (contra reservas, dividendos…)."]'::jsonb, '["Al regularizar, si hay beneficio.", "Al compensar una pérdida con reservas."]'::jsonb, 'Acreedor si hay beneficio; deudor si hay pérdida.', '[]'::jsonb, 'Regularización a 31 de diciembre: ingresos 30.000 € y gastos 25.000 €.', '[{"subcuenta": "70000000", "nombre": "Ventas de mercaderías", "debe": 30000, "haber": 0}, {"subcuenta": "6xxxxxxx", "nombre": "Gastos del grupo 6", "debe": 0, "haber": 25000}, {"subcuenta": "12900000", "nombre": "Resultado del ejercicio", "debe": 0, "haber": 5000}]'::jsonb, 'La 129 guarda el resultado hasta que la junta decide su destino (Operaciones societarias): reservas, dividendos o compensar pérdidas. Si es pérdida y no se compensa, pasa a la 121.'),
('170', 'Préstamos y otras deudas con bancos que vencen a más de un año.', '["Al reclasificar a corto plazo la parte que vence en los próximos 12 meses (contra la 520).", "Al cancelar anticipadamente."]'::jsonb, '["Al recibir el préstamo."]'::jsonb, 'Acreedor. Pasivo no corriente.', '[9]'::jsonb, 'Préstamo de 20.000 € a 5 años ingresado en el banco; a fin de año vencen 3.800 € en los 12 meses siguientes.', '[{"subcuenta": "57200001", "nombre": "Banco", "debe": 20000, "haber": 0}, {"subcuenta": "17000001", "nombre": "Préstamo a l/p – Banco 1", "debe": 0, "haber": 20000}, {"subcuenta": "17000001", "nombre": "Reclasificación a c/p", "debe": 3800, "haber": 0}, {"subcuenta": "52000001", "nombre": "Préstamo a c/p – Banco 1", "debe": 0, "haber": 3800}]'::jsonb, 'Sin la reclasificación, el balance infla el pasivo a largo y los ratios de liquidez salen mejor de lo que son.'),
('173', 'Proveedores de inmovilizado a largo plazo: lo que se debe por la compra de inmovilizado con vencimiento superior a un año.', '["Al pagar o al reclasificar a corto plazo (contra la 523)."]'::jsonb, '["Al recibir el inmovilizado y la factura."]'::jsonb, 'Acreedor. Pasivo no corriente.', '[2, 9]'::jsonb, 'Ver la cuenta 523.', '[]'::jsonb, 'La compra de inmovilizado no va a la 400: la 400 es solo para existencias.'),
('211', 'Construcciones: edificios en general (naves, oficinas, locales) cualquiera que sea su destino.', '["Al comprar o construir el edificio, por su precio de adquisición o coste de producción."]'::jsonb, '["Al venderlo o darlo de baja."]'::jsonb, 'Deudor. Activo no corriente.', '[2, 3]'::jsonb, '', '[]'::jsonb, 'El terreno va aparte, en la 210, porque no se amortiza.'),
('213', 'Maquinaria: máquinas para la producción o la actividad (segadoras, cámaras frigoríficas industriales, líneas de envasado…).', '["Al comprarla, por su precio de adquisición: precio + gastos hasta su puesta en funcionamiento (transporte, instalación). El IGIC soportado deducible no forma parte del coste."]'::jsonb, '["Al venderla o darla de baja."]'::jsonb, 'Deudor. Activo no corriente.', '[2, 3]'::jsonb, 'Compra de una segadora por 60.000 € + IGIC 7 %, pagadera a 6 meses.', '[{"subcuenta": "21300000", "nombre": "Maquinaria", "debe": 60000, "haber": 0}, {"subcuenta": "47210007", "nombre": "IGIC soportado 7 %", "debe": 4200, "haber": 0}, {"subcuenta": "52300001", "nombre": "Proveedor de inmovilizado c/p", "debe": 0, "haber": 64200}]'::jsonb, ''),
('216', 'Mobiliario: muebles, estanterías y equipos de oficina (excepto los informáticos, que van a la 217).', '["Al comprarlo."]'::jsonb, '["Al venderlo o darlo de baja."]'::jsonb, 'Deudor. Activo no corriente.', '[2]'::jsonb, 'Estanterías para el almacén por 6.000 € + IGIC 7 %, a 90 días.', '[{"subcuenta": "21600000", "nombre": "Mobiliario", "debe": 6000, "haber": 0}, {"subcuenta": "47210007", "nombre": "IGIC soportado 7 %", "debe": 420, "haber": 0}, {"subcuenta": "52300001", "nombre": "Muebles Tenerife S.L.", "debe": 0, "haber": 6420}]'::jsonb, ''),
('217', 'Equipos para procesos de información: ordenadores y demás equipos informáticos.', '["Al comprarlos."]'::jsonb, '["Al venderlos o darlos de baja."]'::jsonb, 'Deudor. Activo no corriente.', '[2]'::jsonb, '', '[]'::jsonb, 'Los programas informáticos (licencias) son inmovilizado intangible: cuenta 206.'),
('218', 'Elementos de transporte: vehículos de todo tipo para el transporte de personas o mercancías.', '["Al comprarlos."]'::jsonb, '["Al venderlos o darlos de baja."]'::jsonb, 'Deudor. Activo no corriente.', '[2]'::jsonb, '', '[]'::jsonb, ''),
('281', 'Amortización acumulada del inmovilizado material: suma de las amortizaciones dotadas año a año. Se desglosa por tipo de bien (2811 construcciones, 2813 maquinaria, 2816 mobiliario, 2817 equipos informáticos, 2818 elementos de transporte…).', '["Al dar de baja o vender el bien, por la amortización acumulada hasta ese momento."]'::jsonb, '["Al dotar la amortización de cada periodo (contra la 681)."]'::jsonb, 'Acreedor. Cuenta correctora: resta del inmovilizado en el activo.', '[2, 3]'::jsonb, 'Amortización mensual de un mobiliario de 6.000 € con vida útil de 10 años (lineal).', '[{"subcuenta": "68100000", "nombre": "Amortización del inmovilizado material", "debe": 50, "haber": 0}, {"subcuenta": "28160000", "nombre": "Amortización acumulada de mobiliario", "debe": 0, "haber": 50}]'::jsonb, 'Usa la subcuenta del mismo bien: el mobiliario (216) se amortiza en la 2816.'),
('300', 'Mercaderías: bienes que la empresa compra para revenderlos sin transformarlos.', '["Al cierre, por las existencias finales (contra la 610)."]'::jsonb, '["Al cierre, por las existencias iniciales (contra la 610)."]'::jsonb, 'Deudor. Activo corriente.', '[10]'::jsonb, 'Al cierre, existencias iniciales 8.000 € y finales 11.000 €.', '[{"subcuenta": "61000000", "nombre": "Variación de existencias", "debe": 8000, "haber": 0}, {"subcuenta": "30000000", "nombre": "Mercaderías", "debe": 0, "haber": 8000}, {"subcuenta": "30000000", "nombre": "Mercaderías", "debe": 11000, "haber": 0}, {"subcuenta": "61000000", "nombre": "Variación de existencias", "debe": 0, "haber": 11000}]'::jsonb, 'En el método del PGC, las compras van a la 600, no aquí. La cuenta 300 solo se mueve al cierre. El inventario permanente se lleva en el ERP.'),
('310', 'Materias primas: lo que se transforma en el proceso productivo (en una tabaquera, la hoja de tabaco).', '["Al cierre, por las existencias finales (contra la 611)."]'::jsonb, '["Al cierre, por las existencias iniciales (contra la 611)."]'::jsonb, 'Deudor. Activo corriente.', '[10]'::jsonb, '', '[]'::jsonb, 'Su variación va a la 611 y forma parte de los aprovisionamientos.'),
('350', 'Productos terminados: lo que la empresa fabrica y tiene listo para vender.', '["Al cierre, por las existencias finales (contra la 712)."]'::jsonb, '["Al cierre, por las existencias iniciales (contra la 712)."]'::jsonb, 'Deudor. Activo corriente.', '[10]'::jsonb, '', '[]'::jsonb, 'Su variación va al grupo 7 (712), no al 6: es la línea 2 de la cuenta de resultados. La subactividad y las mermas anormales no forman parte de su valor.'),
('400', 'Proveedores: deudas con los suministradores de mercaderías y demás bienes que se compran para la actividad (existencias). Una subcuenta por proveedor.', '["Al pagarles.", "Por devoluciones, descuentos y rappels que nos conceden.", "Al cancelar la deuda con efectos (401)."]'::jsonb, '["Al recibir la factura de compra, por el total con IGIC."]'::jsonb, 'Acreedor. Pasivo corriente.', '[9, 10]'::jsonb, 'Compra de mercaderías a Frutas del Norte S.L. por 10.000 € + IGIC 7 %, a 60 días.', '[{"subcuenta": "60000000", "nombre": "Compras de mercaderías", "debe": 10000, "haber": 0}, {"subcuenta": "47210007", "nombre": "IGIC soportado 7 %", "debe": 700, "haber": 0}, {"subcuenta": "40000001", "nombre": "Frutas del Norte S.L.", "debe": 0, "haber": 10700}]'::jsonb, 'Solo para existencias. Los servicios van a la 410 y el inmovilizado a la 523 o la 173.'),
('4009', 'Proveedores, facturas pendientes de recibir o de formalizar: mercancía ya recibida cuya factura no ha llegado al cierre.', '["Al recibir la factura (contra la 400)."]'::jsonb, '["Al cierre, por la mercancía recibida sin factura."]'::jsonb, 'Acreedor. Pasivo corriente.', '[10]'::jsonb, 'A 31 de octubre ha llegado mercancía por 2.000 € sin factura.', '[{"subcuenta": "60000000", "nombre": "Compras de mercaderías", "debe": 2000, "haber": 0}, {"subcuenta": "40090000", "nombre": "Facturas pendientes de recibir", "debe": 0, "haber": 2000}]'::jsonb, 'Va sin IGIC: el impuesto solo se deduce con la factura. Es la "cuenta puente" del circuito de compras (WE/RE en SAP).'),
('407', 'Anticipos a proveedores: entregas de dinero a cuenta de compras futuras.', '["Al entregar el anticipo."]'::jsonb, '["Al recibir la factura, descontando el anticipo."]'::jsonb, 'Deudor. Activo corriente.', '[10]'::jsonb, '', '[]'::jsonb, 'El anticipo ya lleva IGIC si así lo dice la factura del anticipo.'),
('410', 'Acreedores por prestaciones de servicios: deudas con quienes nos prestan servicios (luz, asesoría, reparaciones, alquiler). Una subcuenta por acreedor.', '["Al pagarles."]'::jsonb, '["Al recibir la factura, por el total menos las retenciones."]'::jsonb, 'Acreedor. Pasivo corriente.', '[9]'::jsonb, 'Factura de la abogada (autónoma): 1.000 € + IGIC 7 %, retención de IRPF del 15 %.', '[{"subcuenta": "62300000", "nombre": "Servicios de profesionales independientes", "debe": 1000, "haber": 0}, {"subcuenta": "47210007", "nombre": "IGIC soportado 7 %", "debe": 70, "haber": 0}, {"subcuenta": "47510001", "nombre": "Retenciones (modelo 111)", "debe": 0, "haber": 150}, {"subcuenta": "41000003", "nombre": "Abogada", "debe": 0, "haber": 920}]'::jsonb, 'Nombra cada subcuenta por el tercero ("Eléctrica del Sur"), nunca por la categoría ("Suministros").'),
('430', 'Clientes: créditos con los compradores de nuestras mercaderías, productos o servicios. Una subcuenta por cliente.', '["Al emitir la factura de venta, por el total con IGIC."]'::jsonb, '["Al cobrar.", "Por devoluciones, descuentos y rappels que concedemos.", "Al pasar a dudoso cobro (436)."]'::jsonb, 'Deudor. Activo corriente.', '[9, 14]'::jsonb, 'Venta a Hotel Atlántico por 22.500 € + IGIC 7 %, a 30 días.', '[{"subcuenta": "43000001", "nombre": "Hotel Atlántico S.L.", "debe": 24075, "haber": 0}, {"subcuenta": "70000000", "nombre": "Ventas de mercaderías", "debe": 0, "haber": 22500}, {"subcuenta": "47710007", "nombre": "IGIC repercutido 7 %", "debe": 0, "haber": 1575}]'::jsonb, 'El cobro no toca el IGIC: el impuesto nace con la factura.'),
('436', 'Clientes de dudoso cobro: créditos con clientes de los que se duda que paguen (impagos, concurso de acreedores…).', '["Al traspasar el crédito desde la 430."]'::jsonb, '["Al cobrarlo o al darlo por perdido definitivamente."]'::jsonb, 'Deudor. Activo corriente.', '[9]'::jsonb, 'El cliente de 5.350 € entra en concurso: se traspasa y se dota el deterioro de la base.', '[{"subcuenta": "43600000", "nombre": "Clientes de dudoso cobro", "debe": 5350, "haber": 0}, {"subcuenta": "43000002", "nombre": "Cliente", "debe": 0, "haber": 5350}, {"subcuenta": "69400000", "nombre": "Pérdidas por deterioro de créditos", "debe": 5000, "haber": 0}, {"subcuenta": "49000000", "nombre": "Deterioro de valor de créditos", "debe": 0, "haber": 5000}]'::jsonb, 'Traspasar a la 436 no es un gasto: el gasto es el deterioro (694).'),
('438', 'Anticipos de clientes: dinero recibido de clientes a cuenta de ventas futuras.', '["Al emitir la factura definitiva, descontando el anticipo."]'::jsonb, '["Al recibir el anticipo."]'::jsonb, 'Acreedor. Pasivo corriente.', '[14]'::jsonb, '', '[]'::jsonb, ''),
('460', 'Anticipos de remuneraciones: dinero entregado al personal a cuenta de su nómina.', '["Al entregar el anticipo."]'::jsonb, '["Al descontarlo en la nómina."]'::jsonb, 'Deudor. Activo corriente.', '[]'::jsonb, '', '[]'::jsonb, ''),
('465', 'Remuneraciones pendientes de pago: el sueldo neto que se debe a los trabajadores.', '["Al pagar la nómina."]'::jsonb, '["Al contabilizar la nómina, por el líquido a percibir."]'::jsonb, 'Acreedor. Pasivo corriente.', '[]'::jsonb, 'Ver el ejemplo de la cuenta 640.', '[]'::jsonb, 'También sirve para periodificar las pagas extra que se cobran en junio y diciembre.'),
('4700', 'Hacienda Pública, deudora por IVA (en Canarias, por IGIC): el saldo a favor de la empresa cuando el impuesto soportado supera al repercutido.', '["Al liquidar con resultado a devolver o a compensar."]'::jsonb, '["Al cobrar la devolución o compensarlo en liquidaciones posteriores."]'::jsonb, 'Deudor. Activo corriente.', '[12]'::jsonb, '', '[]'::jsonb, ''),
('472', 'Hacienda Pública, IVA soportado (en Canarias, IGIC soportado): el impuesto que nos repercuten en las compras y gastos y que podemos deducir.', '["Al recibir facturas con impuesto deducible."]'::jsonb, '["Al liquidar el periodo.", "Por devoluciones o descuentos que reducen la base."]'::jsonb, 'Deudor. Se salda en cada liquidación.', '[12]'::jsonb, 'Liquidación del trimestre: soportado 1.835,96 €, repercutido 2.000,60 €.', '[{"subcuenta": "47710007", "nombre": "IGIC repercutido 7 %", "debe": 2000.6, "haber": 0}, {"subcuenta": "47210007", "nombre": "IGIC soportado 7 %", "debe": 0, "haber": 1835.96}, {"subcuenta": "47500000", "nombre": "H.P. acreedora por IGIC", "debe": 0, "haber": 164.64}]'::jsonb, 'El PGC la llama "IVA soportado". En Canarias se usa la misma cuenta para el IGIC (la NRV 12.ª los trata igual).'),
('473', 'Hacienda Pública, retenciones y pagos a cuenta: retenciones que otros nos practican (por ejemplo, el banco sobre los intereses) y pagos fraccionados del Impuesto sobre Sociedades.', '["Al sufrir la retención o hacer el pago fraccionado."]'::jsonb, '["Al calcular el Impuesto sobre Sociedades del año (contra la 4752)."]'::jsonb, 'Deudor. Activo corriente.', '[13]'::jsonb, '', '[]'::jsonb, 'No confundir con la 4751: esa son las retenciones que practicamos nosotros.'),
('4750', 'Hacienda Pública, acreedora por IVA (en Canarias, por IGIC): el impuesto que hay que ingresar tras la liquidación.', '["Al pagar (modelo 303 en la Península; modelo 420 a la Agencia Tributaria Canaria)."]'::jsonb, '["Al liquidar con resultado a ingresar."]'::jsonb, 'Acreedor. Pasivo corriente.', '[12]'::jsonb, 'Ver el ejemplo de la cuenta 472.', '[]'::jsonb, ''),
('4751', 'Hacienda Pública, acreedora por retenciones practicadas: el IRPF que retenemos a trabajadores, profesionales y arrendadores y que ingresamos en su nombre.', '["Al ingresarlo: modelo 111 (trabajo y profesionales) y modelo 115 (alquileres)."]'::jsonb, '["Al contabilizar la nómina o la factura con retención."]'::jsonb, 'Acreedor. Pasivo corriente.', '[]'::jsonb, 'Ver los ejemplos de las cuentas 410 y 640.', '[]'::jsonb, 'Va siempre al Haber: retienes un dinero que no es tuyo. La retención se calcula sobre la base, sin impuesto.'),
('4752', 'Hacienda Pública, acreedora por Impuesto sobre Sociedades: lo que queda por pagar del impuesto del año.', '["Al pagarlo (modelo 200, normalmente en julio)."]'::jsonb, '["Al calcular el impuesto del ejercicio."]'::jsonb, 'Acreedor. Pasivo corriente.', '[13]'::jsonb, 'Impuesto de 26.250 € sin retenciones ni pagos a cuenta.', '[{"subcuenta": "63000000", "nombre": "Impuesto corriente", "debe": 26250, "haber": 0}, {"subcuenta": "47520000", "nombre": "H.P. acreedora por Impuesto sobre Sociedades", "debe": 0, "haber": 26250}]'::jsonb, ''),
('476', 'Organismos de la Seguridad Social, acreedores: cotizaciones del trabajador y de la empresa pendientes de ingresar.', '["Al pagar a la Tesorería General de la Seguridad Social (el mes siguiente)."]'::jsonb, '["Al contabilizar la nómina, por la cuota obrera más la patronal."]'::jsonb, 'Acreedor. Pasivo corriente.', '[]'::jsonb, 'Ver el ejemplo de la cuenta 640.', '[]'::jsonb, 'No confundir con la 4752.'),
('477', 'Hacienda Pública, IVA repercutido (en Canarias, IGIC repercutido): el impuesto que cobramos en nuestras ventas.', '["Al liquidar el periodo.", "Por devoluciones, descuentos o rappels concedidos."]'::jsonb, '["Al emitir facturas de venta."]'::jsonb, 'Acreedor. Se salda en cada liquidación.', '[12]'::jsonb, 'Ver los ejemplos de las cuentas 430 y 472.', '[]'::jsonb, ''),
('480', 'Gastos anticipados: gastos pagados en este ejercicio (o mes) que corresponden al siguiente.', '["Al cierre, por la parte del gasto que corresponde al futuro."]'::jsonb, '["Al empezar el periodo siguiente, al imputarla como gasto."]'::jsonb, 'Deudor. Activo corriente.', '[]'::jsonb, 'Seguro anual de 1.200 € pagado el 1 de octubre: a 31 de diciembre quedan 900 € del año siguiente.', '[{"subcuenta": "48000000", "nombre": "Gastos anticipados", "debe": 900, "haber": 0}, {"subcuenta": "62500000", "nombre": "Primas de seguros", "debe": 0, "haber": 900}]'::jsonb, 'Es el principio de devengo: el gasto va al periodo que cubre.'),
('485', 'Ingresos anticipados: ingresos cobrados o facturados en este ejercicio que corresponden al siguiente.', '["Al empezar el periodo siguiente, al imputarlos como ingreso."]'::jsonb, '["Al cierre, por la parte del ingreso que corresponde al futuro."]'::jsonb, 'Acreedor. Pasivo corriente.', '[14]'::jsonb, '', '[]'::jsonb, ''),
('490', 'Deterioro de valor de créditos por operaciones comerciales: estimación de la parte de los clientes que no se cobrará.', '["Al cierre siguiente, al revertir la dotación anterior (contra la 794).", "Al dar el crédito por perdido."]'::jsonb, '["Al dotar el deterioro (contra la 694)."]'::jsonb, 'Acreedor. Cuenta correctora: resta de los clientes en el activo.', '[9]'::jsonb, 'Ver el ejemplo de la cuenta 436.', '[]'::jsonb, ''),
('520', 'Deudas a corto plazo con entidades de crédito: préstamos y créditos bancarios que vencen en menos de un año, incluida la parte a corto de los préstamos a largo.', '["Al pagar las cuotas."]'::jsonb, '["Al recibir un préstamo a corto o al reclasificar desde la 170."]'::jsonb, 'Acreedor. Pasivo corriente.', '[9]'::jsonb, 'Ver el ejemplo de la cuenta 170.', '[]'::jsonb, 'Las pólizas de crédito usan la 5201.'),
('523', 'Proveedores de inmovilizado a corto plazo: deudas por la compra de inmovilizado que vencen en menos de un año.', '["Al pagar."]'::jsonb, '["Al recibir el bien y su factura."]'::jsonb, 'Acreedor. Pasivo corriente.', '[2, 9]'::jsonb, 'Ver los ejemplos de las cuentas 213 y 216.', '[]'::jsonb, 'No es la 400: la 400 es para existencias.'),
('527', 'Intereses a corto plazo de deudas con entidades de crédito: intereses devengados y aún no pagados.', '["Al pagar los intereses con la cuota."]'::jsonb, '["Al cierre, por los intereses devengados no vencidos."]'::jsonb, 'Acreedor. Pasivo corriente.', '[9]'::jsonb, 'Préstamo de 20.000 € al 6 %: intereses de octubre, que se pagan en noviembre.', '[{"subcuenta": "66200000", "nombre": "Intereses de deudas", "debe": 100, "haber": 0}, {"subcuenta": "52700001", "nombre": "Intereses a c/p – Banco 1", "debe": 0, "haber": 100}]'::jsonb, ''),
('551', 'Cuenta corriente con socios y administradores: préstamos, cobros y pagos entre la empresa y sus socios o administradores.', '["Cuando la empresa paga o presta dinero al socio."]'::jsonb, '["Cuando el socio paga o presta dinero a la empresa."]'::jsonb, 'Deudor o acreedor según el saldo.', '[]'::jsonb, '', '[]'::jsonb, 'Si el saldo es deudor, es un activo; si es acreedor, un pasivo.'),
('570', 'Caja: dinero en efectivo.', '["Al cobrar en efectivo."]'::jsonb, '["Al pagar en efectivo."]'::jsonb, 'Deudor. Nunca puede ser acreedor.', '[]'::jsonb, '', '[]'::jsonb, 'Una caja con saldo acreedor es un error seguro: no se puede sacar más dinero del que hay.'),
('572', 'Bancos e instituciones de crédito, cuentas a la vista: saldos en cuentas corrientes. Una subcuenta por banco o cuenta.', '["Al cobrar o ingresar dinero."]'::jsonb, '["Al pagar o transferir."]'::jsonb, 'Deudor. Si queda en descubierto (saldo acreedor), en el balance va como deuda a corto plazo.', '[]'::jsonb, '', '[]'::jsonb, 'Es la cuenta que se concilia cada mes con el extracto bancario.'),
('600', 'Compras de mercaderías: aprovisionamiento de bienes para revenderlos.', '["Al recibir la factura, por la base: precio − descuentos comerciales en factura + transporte y otros gastos incluidos en la factura."]'::jsonb, '["Al regularizar al cierre (contra la 129)."]'::jsonb, 'Deudor. Gasto: línea 4 de la cuenta de resultados (aprovisionamientos).', '[10]'::jsonb, 'Compra de 10.000 € con un descuento comercial del 5 % en factura y 150 € de transporte, IGIC 7 %.', '[{"subcuenta": "60000000", "nombre": "Compras de mercaderías", "debe": 9650, "haber": 0}, {"subcuenta": "47210007", "nombre": "IGIC soportado 7 %", "debe": 675.5, "haber": 0}, {"subcuenta": "40000001", "nombre": "Proveedor", "debe": 0, "haber": 10325.5}]'::jsonb, 'Sin IGIC: el impuesto deducible no es coste. El descuento en factura no tiene cuenta propia: reduce la compra.'),
('601', 'Compras de materias primas: aprovisionamiento de lo que se va a transformar.', '["Al recibir la factura, por la base."]'::jsonb, '["Al regularizar."]'::jsonb, 'Deudor. Gasto (aprovisionamientos).', '[10]'::jsonb, '', '[]'::jsonb, ''),
('606', 'Descuentos sobre compras por pronto pago: descuentos que nos conceden por pagar antes, fuera de factura.', '["Al regularizar."]'::jsonb, '["Al obtener el descuento."]'::jsonb, 'Acreedor. Reduce los aprovisionamientos.', '[10]'::jsonb, 'Pagamos 9.255,50 € al proveedor con un 2 % de descuento sobre la base de 8.650 €.', '[{"subcuenta": "40000001", "nombre": "Proveedor", "debe": 9255.5, "haber": 0}, {"subcuenta": "60600000", "nombre": "Descuentos sobre compras por pronto pago", "debe": 0, "haber": 173}, {"subcuenta": "47210007", "nombre": "IGIC soportado 7 %", "debe": 0, "haber": 12.11}, {"subcuenta": "57200001", "nombre": "Banco", "debe": 0, "haber": 9070.39}]'::jsonb, 'Reduce también el IGIC. En el plan de 1990 era un ingreso financiero; ahora es comercial.'),
('608', 'Devoluciones de compras: mercancías que devolvemos al proveedor.', '["Al regularizar."]'::jsonb, '["Al devolver la mercancía, por la base."]'::jsonb, 'Acreedor. Reduce los aprovisionamientos.', '[10]'::jsonb, 'Devolvemos mercancía defectuosa por 1.000 € de base.', '[{"subcuenta": "40000001", "nombre": "Proveedor", "debe": 1070, "haber": 0}, {"subcuenta": "60800000", "nombre": "Devoluciones de compras", "debe": 0, "haber": 1000}, {"subcuenta": "47210007", "nombre": "IGIC soportado 7 %", "debe": 0, "haber": 70}]'::jsonb, 'El IGIC sigue a la base: si devuelves la mercancía, devuelves su impuesto.'),
('609', 'Rappels por compras: descuentos por volumen de compras, normalmente al final de un periodo.', '["Al regularizar."]'::jsonb, '["Al concederse el rappel."]'::jsonb, 'Acreedor. Reduce los aprovisionamientos.', '[10]'::jsonb, '', '[]'::jsonb, ''),
('610', 'Variación de existencias de mercaderías: diferencia entre las existencias iniciales y las finales.', '["Al cierre, por las existencias iniciales."]'::jsonb, '["Al cierre, por las existencias finales."]'::jsonb, 'Deudor si las existencias bajan; acreedor si suben. Forma parte de los aprovisionamientos.', '[10]'::jsonb, 'Ver el ejemplo de la cuenta 300.', '[]'::jsonb, 'Coste de lo vendido = compras + existencias iniciales − existencias finales.'),
('621', 'Arrendamientos y cánones: alquileres de locales, naves, maquinaria o vehículos.', '["Al devengarse el alquiler."]'::jsonb, '["Al regularizar."]'::jsonb, 'Deudor. Otros gastos de explotación.', '[8]'::jsonb, 'Alquiler del local a un particular: 1.000 € + IGIC 7 %, retención del 19 %.', '[{"subcuenta": "62100000", "nombre": "Arrendamientos", "debe": 1000, "haber": 0}, {"subcuenta": "47210007", "nombre": "IGIC soportado 7 %", "debe": 70, "haber": 0}, {"subcuenta": "47510002", "nombre": "Retenciones de alquileres (modelo 115)", "debe": 0, "haber": 190}, {"subcuenta": "41000001", "nombre": "Arrendador", "debe": 0, "haber": 880}]'::jsonb, 'Si el arrendador es persona física o sociedad y el inmueble es urbano, normalmente hay retención, salvo excepciones.'),
('622', 'Reparaciones y conservación: mantenimiento y reparaciones que conservan los bienes sin aumentar su vida útil.', '["Al recibir la factura."]'::jsonb, '["Al regularizar."]'::jsonb, 'Deudor. Otros gastos de explotación.', '[3]'::jsonb, '', '[]'::jsonb, 'Si la reparación alarga la vida útil o mejora el bien, se activa como mayor valor del inmovilizado (NRV 3.ª).'),
('623', 'Servicios de profesionales independientes: abogados, asesores, notarios, auditores…', '["Al recibir la factura, por la base."]'::jsonb, '["Al regularizar."]'::jsonb, 'Deudor. Otros gastos de explotación.', '[]'::jsonb, 'Ver el ejemplo de la cuenta 410.', '[]'::jsonb, 'Si el profesional es persona física, normalmente hay retención de IRPF.'),
('624', 'Transportes: transporte a cargo de la empresa realizado por terceros, cuando no forma parte del precio de compra.', '["Al recibir la factura del transportista."]'::jsonb, '["Al regularizar."]'::jsonb, 'Deudor. Otros gastos de explotación.', '[10]'::jsonb, '', '[]'::jsonb, 'Si el transporte va en la factura del proveedor de la mercancía, suma al precio de compra (600).'),
('625', 'Primas de seguros.', '["Al pagar o devengar la prima."]'::jsonb, '["Al periodificar la parte del futuro (contra la 480).", "Al regularizar."]'::jsonb, 'Deudor. Otros gastos de explotación.', '[]'::jsonb, 'Ver el ejemplo de la cuenta 480.', '[]'::jsonb, 'Los seguros están exentos de IGIC.'),
('626', 'Servicios bancarios y similares: comisiones bancarias.', '["Al cargarlas el banco."]'::jsonb, '["Al regularizar."]'::jsonb, 'Deudor. Otros gastos de explotación.', '[]'::jsonb, '', '[]'::jsonb, 'Los intereses no van aquí: van a la 662. Las comisiones bancarias están exentas de IGIC.'),
('628', 'Suministros: electricidad, agua, gas y otros suministros que no se almacenan.', '["Al recibir la factura."]'::jsonb, '["Al regularizar."]'::jsonb, 'Deudor. Otros gastos de explotación.', '[]'::jsonb, '', '[]'::jsonb, ''),
('629', 'Otros servicios: gastos de viaje, material de oficina, teléfono y otros no incluidos en las cuentas anteriores.', '["Al recibir la factura."]'::jsonb, '["Al regularizar."]'::jsonb, 'Deudor. Otros gastos de explotación.', '[]'::jsonb, '', '[]'::jsonb, ''),
('6300', 'Impuesto corriente: el gasto por el Impuesto sobre Sociedades del ejercicio.', '["Al calcular el impuesto: (resultado contable ± ajustes fiscales) × tipo."]'::jsonb, '["Al regularizar."]'::jsonb, 'Deudor. Línea «Impuestos sobre beneficios» de la cuenta de resultados.', '[13]'::jsonb, 'Ver el ejemplo de la cuenta 4752.', '[]'::jsonb, 'Las multas no son deducibles: se suman al resultado para calcular la base imponible.'),
('631', 'Otros tributos: impuestos que paga la empresa como contribuyente, como el IBI o el IAE.', '["Al devengarse."]'::jsonb, '["Al regularizar."]'::jsonb, 'Deudor. Otros gastos de explotación.', '[]'::jsonb, '', '[]'::jsonb, ''),
('640', 'Sueldos y salarios: remuneración bruta del personal.', '["Al contabilizar la nómina, por el bruto."]'::jsonb, '["Al regularizar."]'::jsonb, 'Deudor. Gastos de personal.', '[]'::jsonb, 'Nómina: bruto 1.800 €, Seguridad Social del trabajador 114 €, IRPF 180 € y Seguridad Social de la empresa 576 €.', '[{"subcuenta": "64000000", "nombre": "Sueldos y salarios", "debe": 1800, "haber": 0}, {"subcuenta": "64200000", "nombre": "Seguridad Social a cargo de la empresa", "debe": 576, "haber": 0}, {"subcuenta": "47600000", "nombre": "Seguridad Social, acreedores", "debe": 0, "haber": 690}, {"subcuenta": "47510001", "nombre": "Retenciones (modelo 111)", "debe": 0, "haber": 180}, {"subcuenta": "46500000", "nombre": "Remuneraciones pendientes", "debe": 0, "haber": 1506}]'::jsonb, 'Coste total para la empresa = bruto + Seguridad Social de la empresa (2.376 €).'),
('642', 'Seguridad Social a cargo de la empresa: la cuota patronal.', '["Al contabilizar la nómina."]'::jsonb, '["Al regularizar."]'::jsonb, 'Deudor. Gastos de personal.', '[]'::jsonb, 'Ver el ejemplo de la cuenta 640.', '[]'::jsonb, 'Su contrapartida es la 476, junto con la cuota del trabajador.'),
('662', 'Intereses de deudas: intereses de préstamos y otras deudas.', '["Al devengarse los intereses."]'::jsonb, '["Al regularizar."]'::jsonb, 'Deudor. Gastos financieros.', '[9]'::jsonb, 'Ver el ejemplo de la cuenta 527.', '[]'::jsonb, 'Están fuera del EBITDA y del EBIT.'),
('681', 'Amortización del inmovilizado material: depreciación del periodo por el uso y el paso del tiempo.', '["Al dotar la amortización."]'::jsonb, '["Al regularizar."]'::jsonb, 'Deudor. Línea 8 de la cuenta de resultados.', '[2]'::jsonb, 'Ver el ejemplo de la cuenta 281.', '[]'::jsonb, 'Se amortiza desde que el bien entra en funcionamiento, en proporción al tiempo.'),
('694', 'Pérdidas por deterioro de créditos por operaciones comerciales: gasto por la estimación de clientes incobrables.', '["Al dotar el deterioro."]'::jsonb, '["Al regularizar."]'::jsonb, 'Deudor. Otros gastos de explotación.', '[9]'::jsonb, 'Ver el ejemplo de la cuenta 436.', '[]'::jsonb, ''),
('700', 'Ventas de mercaderías.', '["Al regularizar."]'::jsonb, '["Al emitir la factura, por la base: precio − descuentos comerciales en factura."]'::jsonb, 'Acreedor. Línea 1 de la cuenta de resultados (cifra de negocios).', '[14]'::jsonb, 'Ver el ejemplo de la cuenta 430.', '[]'::jsonb, 'Sin IGIC: el impuesto repercutido no es ingreso.'),
('705', 'Prestaciones de servicios.', '["Al regularizar."]'::jsonb, '["Al facturar el servicio, por la base."]'::jsonb, 'Acreedor. Cifra de negocios.', '[14]'::jsonb, '', '[]'::jsonb, ''),
('706', 'Descuentos sobre ventas por pronto pago: descuentos que concedemos a clientes por pagar antes, fuera de factura.', '["Al conceder el descuento."]'::jsonb, '["Al regularizar."]'::jsonb, 'Deudor. Reduce la cifra de negocios.', '[14]'::jsonb, 'El cliente paga antes y le damos un 2 % sobre 6.500 €.', '[{"subcuenta": "57200001", "nombre": "Banco", "debe": 6815.9, "haber": 0}, {"subcuenta": "70600000", "nombre": "Descuentos sobre ventas por pronto pago", "debe": 130, "haber": 0}, {"subcuenta": "47710007", "nombre": "IGIC repercutido 7 %", "debe": 9.1, "haber": 0}, {"subcuenta": "43000001", "nombre": "Cliente", "debe": 0, "haber": 6955}]'::jsonb, ''),
('708', 'Devoluciones de ventas: mercancías que nos devuelven los clientes.', '["Al recibir la devolución, por la base."]'::jsonb, '["Al regularizar."]'::jsonb, 'Deudor. Reduce la cifra de negocios.', '[14]'::jsonb, 'Un cliente devuelve mercancía por 2.000 € de base.', '[{"subcuenta": "70800000", "nombre": "Devoluciones de ventas", "debe": 2000, "haber": 0}, {"subcuenta": "47710007", "nombre": "IGIC repercutido 7 %", "debe": 140, "haber": 0}, {"subcuenta": "43000002", "nombre": "Cliente", "debe": 0, "haber": 2140}]'::jsonb, 'Truco: 706 = pago antes; 708 = la mercancía vuelve; 709 = volumen.'),
('709', 'Rappels sobre ventas: descuentos por volumen que concedemos, normalmente al final de un periodo.', '["Al conceder el rappel."]'::jsonb, '["Al regularizar."]'::jsonb, 'Deudor. Reduce la cifra de negocios.', '[14]'::jsonb, 'Rappel del 3 % sobre unas ventas netas de 16.000 €.', '[{"subcuenta": "70900000", "nombre": "Rappels sobre ventas", "debe": 480, "haber": 0}, {"subcuenta": "47710007", "nombre": "IGIC repercutido 7 %", "debe": 33.6, "haber": 0}, {"subcuenta": "43000002", "nombre": "Cliente", "debe": 0, "haber": 513.6}]'::jsonb, ''),
('752', 'Ingresos por arrendamientos: alquileres que cobramos por bienes que cedemos.', '["Al regularizar."]'::jsonb, '["Al devengarse el alquiler."]'::jsonb, 'Acreedor. Otros ingresos de explotación.', '[8]'::jsonb, '', '[]'::jsonb, ''),
('769', 'Otros ingresos financieros: intereses de cuentas y otros rendimientos financieros no recogidos en otras cuentas.', '["Al regularizar."]'::jsonb, '["Al devengarse."]'::jsonb, 'Acreedor. Ingresos financieros.', '[9]'::jsonb, '', '[]'::jsonb, 'Si el banco retiene, la retención va a la 473.'),
('794', 'Reversión del deterioro de créditos por operaciones comerciales: ingreso cuando el deterioro dotado ya no es necesario.', '["Al regularizar."]'::jsonb, '["Al revertir el deterioro (contra la 490)."]'::jsonb, 'Acreedor. Otros gastos de explotación (en negativo).', '[9]'::jsonb, '', '[]'::jsonb, '')
insert into erp.pgc_valuation_rules (number, title, summary) values
(1, 'Desarrollo del Marco Conceptual', 'Remite a los principios y criterios del Marco Conceptual para todo lo que no regulen las normas siguientes.'),
(2, 'Inmovilizado material', 'Se valora por su precio de adquisición o coste de producción, más los gastos hasta su puesta en funcionamiento. El IVA o IGIC solo forma parte del coste si no es deducible. Se amortiza de forma sistemática según su vida útil y se revisa si hay deterioro.'),
(3, 'Normas particulares sobre el inmovilizado material', 'Reglas para solares, construcciones, instalaciones, utillaje, equipos informáticos y, sobre todo, para distinguir reparación (gasto) de mejora o ampliación (más valor del bien).'),
(4, 'Inversiones inmobiliarias', 'Inmuebles que se tienen para obtener rentas o plusvalías, no para la actividad. Se valoran como el inmovilizado material.'),
(5, 'Inmovilizado intangible', 'Activos sin sustancia física: aplicaciones informáticas, patentes, desarrollo… Exige que sean identificables. Se amortizan según su vida útil; si no se puede estimar, en 10 años.'),
(6, 'Normas particulares sobre el inmovilizado intangible', 'Reglas para investigación y desarrollo, propiedad industrial, fondo de comercio, derechos de traspaso y aplicaciones informáticas.'),
(7, 'Activos no corrientes y grupos enajenables mantenidos para la venta', 'Activos cuyo valor se recuperará vendiéndolos y no usándolos. Dejan de amortizarse y se valoran al menor entre su valor contable y su valor razonable menos los costes de venta.'),
(8, 'Arrendamientos y otras operaciones de naturaleza similar', 'Distingue el arrendamiento financiero (se trata como una compra financiada: el bien va al activo y la deuda al pasivo) del operativo (la cuota es gasto).'),
(9, 'Instrumentos financieros', 'Clientes, préstamos, inversiones y deudas. Desde 2021 los activos se clasifican, entre otras, en las carteras de coste amortizado y de valor razonable. Regula los deterioros de clientes y los intereses por el método del tipo de interés efectivo.'),
(10, 'Existencias', 'Precio de adquisición o coste de producción. Para bienes intercambiables, precio medio o FIFO (no se admite LIFO). La subactividad y las mermas anormales no se incorporan al coste. Si el valor neto realizable cae por debajo del coste, se dota un deterioro.'),
(11, 'Moneda extranjera', 'Operaciones en otra moneda: se convierten al tipo de cambio de la fecha de la operación, y las diferencias de cambio van a resultados (cuentas 668 y 768).'),
(12, 'IVA, IGIC y otros impuestos indirectos', 'El IVA y el IGIC soportados deducibles no forman parte del precio de compra, y los repercutidos no son ingreso. Si no son deducibles, sí suman al coste del bien o servicio. Menciona expresamente el IGIC.'),
(13, 'Impuestos sobre beneficios', 'El gasto por Impuesto sobre Sociedades tiene una parte corriente (lo que se paga este año) y una diferida (diferencias temporarias entre la contabilidad y la fiscalidad), con activos y pasivos por impuesto diferido.'),
(14, 'Ingresos por ventas y prestación de servicios', 'Desde 2021 sigue un modelo de cinco pasos: contrato, obligaciones, precio, reparto del precio y reconocimiento del ingreso cuando se transfiere el control. Los descuentos y rappels reducen el ingreso.'),
(15, 'Provisiones y contingencias', 'Se reconoce una provisión cuando hay una obligación presente, es probable que haya que pagar y se puede estimar el importe. Las contingencias solo se explican en la memoria.'),
(16, 'Pasivos por retribuciones a largo plazo al personal', 'Compromisos de pensiones y otras retribuciones a largo plazo con los trabajadores, de aportación o de prestación definida.'),
(17, 'Transacciones con pagos basados en instrumentos de patrimonio', 'Retribuciones pagadas con acciones o participaciones de la empresa, o con efectivo referenciado a su valor.'),
(18, 'Subvenciones, donaciones y legados recibidos', 'Las no reintegrables se registran primero en el patrimonio neto y se imputan a resultados en el mismo ritmo que el gasto o la amortización que financian.'),
(19, 'Combinaciones de negocios', 'Compra de negocios o fusiones: se aplica el método de adquisición y puede surgir un fondo de comercio.'),
(20, 'Negocios conjuntos', 'Actividades controladas conjuntamente con otras empresas, como las uniones temporales de empresas.'),
(21, 'Operaciones entre empresas del grupo', 'Las operaciones entre empresas de un mismo grupo se valoran, en general, por su valor razonable.'),
(22, 'Cambios en criterios contables, errores y estimaciones contables', 'Un cambio de criterio o la corrección de un error de años anteriores se aplica de forma retroactiva contra reservas. Un cambio de estimación (por ejemplo, de vida útil) se aplica hacia delante.'),
(23, 'Hechos posteriores al cierre del ejercicio', 'Si un hecho posterior aporta información sobre una situación que ya existía al cierre, se ajustan las cuentas. Si es una situación nueva, solo se informa en la memoria.')
insert into erp.pgc_principles (sort, name, description) values
(1, 'Empresa en funcionamiento', 'Se presume que la empresa seguirá operando en el futuro previsible. Si va a liquidarse, cambian los criterios de valoración.'),
(2, 'Devengo', 'Los ingresos y gastos se registran cuando ocurren, con independencia de cuándo se cobren o paguen.'),
(3, 'Uniformidad', 'Un criterio elegido se mantiene en el tiempo y se aplica a operaciones similares.'),
(4, 'Prudencia', 'Solo se contabilizan los beneficios obtenidos hasta el cierre, pero se tienen en cuenta todos los riesgos conocidos.'),
(5, 'No compensación', 'No se compensan activos con pasivos ni gastos con ingresos, salvo que una norma lo permita.'),
(6, 'Importancia relativa', 'Se admite no aplicar estrictamente un principio cuando el efecto es poco significativo y no altera la imagen fiel.')
