-- =====================================================================
-- 0071 · PGC DE ESTUDIO: libro de consulta del Plan General de Contabilidad · v0.48.0
-- ---------------------------------------------------------------------
-- Diseño validado por Diosvely (diseno-v0.48.0.md). Parte de la especificación y los datos que preparó otro chat
-- (SPEC_pgc_estudio.md · pgc_estudio_seed.json), con las tablas en inglés como el resto de la base de datos (ADR 0003)
-- y los textos en español.
--   · Solo lectura y común a todas las empresas: no toca el plan de cuentas operativo ni la contabilidad.
--   · 9 grupos, 78 subgrupos y 712 cuentas de 4 dígitos: las 703 del PGC de los grupos 1 a 7, la 2804 y 8 de los grupos 8 y 9
--     (impuesto sobre beneficios y subvenciones, v0.44.0), estas sin ficha.
--   · 70 fichas de estudio: uso, cuándo se carga y se abona, saldo, NRV, ejemplo con IGIC del 7 % y «Ojo».
--     PENDIENTES DE VALIDAR POR DIOSVELY (regla A3): pgc_cards.validated = false hasta que las revise.
--   · 23 normas de registro y valoración y 6 principios contables, redactados con palabras propias (no literales).
-- Fuente oficial: RD 1514/2007 y sus modificaciones (RD 1159/2010, 602/2016 y 1/2021), BOE-A-2007-19884.
-- Re-ejecutable.
-- =====================================================================

create table if not exists erp.pgc_groups (
  grp  char(1) primary key,
  name text not null
);
create table if not exists erp.pgc_subgroups (
  subgroup char(2) primary key,
  grp      char(1) not null references erp.pgc_groups (grp),
  name     text not null
);
create index if not exists pgc_subgroups_grp_idx on erp.pgc_subgroups (grp);
create table if not exists erp.pgc_accounts (
  account         varchar(4) primary key,
  subgroup        char(2) not null references erp.pgc_subgroups (subgroup),
  name            text not null,
  statement_lines jsonb not null default '[]'::jsonb      -- dónde aparece en las cuentas anuales (textos)
);
create index if not exists pgc_accounts_subgroup_idx on erp.pgc_accounts (subgroup);
create table if not exists erp.pgc_cards (
  code          varchar(4) primary key,                  -- 3 dígitos (toda la cuenta) o 4 (específica)
  usage         text not null,
  debits        jsonb not null,                          -- cuándo se carga (Debe)
  credits       jsonb not null,                          -- cuándo se abona (Haber)
  balance       text not null,
  nrv           jsonb not null default '[]'::jsonb,      -- números de las NRV que la tratan
  example_text  text not null default '',
  example_lines jsonb not null default '[]'::jsonb,      -- [{subcuenta, nombre, debe, haber}]
  warning       text not null default '',
  validated     boolean not null default false           -- regla A3: hasta que Diosvely la revise
);
create table if not exists erp.pgc_valuation_rules (
  number  int primary key,
  title   text not null,
  summary text not null
);
create table if not exists erp.pgc_principles (
  sort        int primary key,
  name        text not null,
  description text not null
);
comment on table erp.pgc_accounts is 'PGC de estudio: cuentas de 4 dígitos con su sitio en las cuentas anuales (solo lectura)';
comment on table erp.pgc_cards is 'PGC de estudio: fichas de las cuentas (textos propios, pendientes de validar por Diosvely)';

on conflict (grp) do update set name = excluded.name;

on conflict (subgroup) do update set grp = excluded.grp, name = excluded.name;

on conflict (account) do update set subgroup = excluded.subgroup, name = excluded.name, statement_lines = excluded.statement_lines;

on conflict (code) do update set usage = excluded.usage, debits = excluded.debits, credits = excluded.credits, balance = excluded.balance,
  nrv = excluded.nrv, example_text = excluded.example_text, example_lines = excluded.example_lines, warning = excluded.warning;

on conflict (number) do update set title = excluded.title, summary = excluded.summary;

on conflict (sort) do update set name = excluded.name, description = excluded.description;

-- Lectura para quien ha entrado (también los invitados de las demos); nadie escribe desde la web
do $$ declare t text; begin
  foreach t in array array['pgc_groups', 'pgc_subgroups', 'pgc_accounts', 'pgc_cards', 'pgc_valuation_rules', 'pgc_principles'] loop
    execute format('alter table erp.%I enable row level security', t);
    execute format('drop policy if exists read on erp.%I', t);
    execute format('create policy read on erp.%I for select to authenticated using (true)', t);
    execute format('revoke all on erp.%I from anon, public', t);
    execute format('grant select on erp.%I to authenticated', t);
  end loop;
end $$;
